import sys

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n, m = map(int, input[ptr:ptr+2])
    ptr +=2
    a = list(map(int, input[ptr:ptr+n]))
    ptr +=n

    # Preprocess next different array
    next_diff = [0] * n
    next_diff[-1] = -1
    for i in range(n-2, -1, -1):
        if a[i] != a[i+1]:
            next_diff[i] = i+1
        else:
            next_diff[i] = next_diff[i+1]

    output = []
    for _ in range(m):
        l, r, x = map(int, input[ptr:ptr+3])
        ptr +=3
        l -=1
        r -=1
        if a[l] != x:
            output.append(str(l+1))
        else:
            pos = next_diff[l]
            if pos != -1 and pos <= r:
                output.append(str(pos+1))
            else:
                output.append("-1")
    print('\n'.join(output))

if __name__ == "__main__":
    main()

