res = 1

for i in range(1, n + 1):
    if not visited[i]:
        current = i
        cycle_length = 0
        while True:
            visited[current] = True
            current = crush[current - 1]
            cycle_length += 1
            if current == i:
                break
        if cycle_length % 2 == 0:
            res = res * (cycle_length // 2) // math.gcd(res, cycle_length // 2)
        else:
            res = res * cycle_length // math.gcd(res, cycle_length)

