import sys

def is_lucky(num):
    s = str(num)
    for c in s:
        if c != '4' and c != '7':
            return False
    return True

def solve():
    n, k = map(int, sys.stdin.readline().split())

    # Determine the smallest m such that (n - m)! < k <= (n - m + 1)!
    fact = [1] * 21
    for i in range(1, 21):
        fact[i] = fact[i-1] * i

    m = 0
    if n <= 20:
        if k > fact[n]:
            print(-1)
            return
    else:
        m = n - 20

    # The first part: numbers 1..m, their positions are fixed
    # Count lucky numbers in 1..m that are at lucky positions
    res = 0
    for num in range(1, m + 1):
        if is_lucky(num):
            if is_lucky(num):
                res += 1

    # The second part: numbers m+1..n, need to find the (k-1)-th permutation
    if n <= 20 and k > fact[n]:
        print(-1)
        return

    perm_length = min(n, 20)
    remaining = list(range(m + 1, n + 1))
    current_k = k - 1
    permutation = []

    for i in range(perm_length, 0, -1):
        f = fact[i - 1]
        pos = current_k // f
        if pos >= len(remaining):
            print(-1)
            return
        permutation.append(remaining[pos])
        del remaining[pos]
        current_k %= f

    # Check the permutation positions (1-based in the original permutation)
    for idx_in_perm in range(len(permutation)):
        original_pos = m + 1 + idx_in_perm
        num = permutation[idx_in_perm]
        if is_lucky(original_pos) and is_lucky(num):
            res += 1

    print(res)

solve()

