import sys

def main():
    n = int(sys.stdin.readline())
    sequence = [0]
    prefix_adds = []
    total_sum = 0.0
    res = []

    for _ in range(n):
        parts = list(map(int, sys.stdin.readline().split()))
        t = parts[0]

        if t == 1:
            a, x = parts[1], parts[2]
            if a > 0:
                if len(prefix_adds) < a:
                    prefix_adds.extend([0] * (a - len(prefix_adds)))
                for i in range(a):
                    prefix_adds[i] += x
            total_sum += a * x
        elif t == 2:
            k = parts[1]
            sequence.append(k)
            total_sum += k
        elif t == 3:
            last = sequence.pop()
            if len(prefix_adds) > 0:
                last_add = prefix_adds.pop()
                last += last_add
            total_sum -= last

        avg = total_sum / len(sequence)
        res.append("{0:.7f}".format(avg))

    print('\n'.join(res))

