import itertools

def solve():
    heroes = ['Anka', 'Chapay', 'Cleo', 'Troll', 'Dracul', 'Snowy', 'Hexadecimal']
    likes = {h: set() for h in heroes}

    n = int(input())
    for _ in range(n):
        parts = input().split()
        p = parts[0]
        q = parts[2]
        likes[p].add(q)

    a, b, c = map(int, input().split())

    min_diff = float('inf')
    max_likes = 0

    # Generate all possible partitions into 3 non-empty teams
    for partition in itertools.product([0, 1, 2], repeat=7):
        counts = [0, 0, 0]
        for team in partition:
            counts[team] += 1
        if 0 in counts:
            continue

        # Calculate experience differences
        exp = []
        if counts[0] > 0:
            exp.append(a // counts[0])
        if counts[1] > 0:
            exp.append(b // counts[1])
        if counts[2] > 0:
            exp.append(c // counts[2])

        current_diff = max(exp) - min(exp)

        # Calculate total likes
        total_likes = 0
        for i in range(7):
            for j in range(7):
                if partition[i] == partition[j] and heroes[j] in likes[heroes[i]]:
                    total_likes += 1

        if current_diff < min_diff:
            min_diff = current_diff
            max_likes = total_likes
        elif current_diff == min_diff:
            if total_likes > max_likes:
                max_likes = total_likes

    print(min_diff, max_likes)

solve()

