import sys
import math

def solve():
    n, *rest = map(int, sys.stdin.read().split())
    a = rest[:n]

    current_gcd = a[0]
    for num in a[1:]:
        current_gcd = math.gcd(current_gcd, num)
        if current_gcd == 1:
            break

    if current_gcd > 1:
        print("YES")
        print(0)
        return

    operations = 0
    i = 0
    while i < n:
        if a[i] % 2 != 0:
            if i + 1 < n and a[i + 1] % 2 != 0:
                operations += 1
                i += 2
            else:
                operations += 2
                i += 1
        else:
            i += 1

    print("YES")
    print(operations)

solve()

