    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    current_gcd = a[0]
    for num in a[1:]:
        current_gcd = math.gcd(current_gcd, num)
        if current_gcd == 1:
            break

    if current_gcd > 1:
        print("YES")
        print(0)
        return

    operations = 0
    i = 0
    while i < n - 1:
        if a[i] % 2 != 0:
            if a[i+1] % 2 != 0:
                operations += 1
            else:
