import sys
import heapq

def solve():
    n = int(sys.stdin.readline())
    p = list(map(int, sys.stdin.readline().split()))
    a = list(map(int, sys.stdin.readline().split()))
    b = list(map(int, sys.stdin.readline().split()))

    # Create heaps for each color (1-3)
    heaps = {1: [], 2: [], 3: []}
    available = [True] * n

    for i in range(n):
        colors = {a[i], b[i]}
        for color in colors:
            heapq.heappush(heaps[color], (p[i], i))

