    c_list = list(map(int, sys.stdin.readline().split()))
    res = []

    for c in c_list:
        found = None
        while heaps[c]:
            current_p, current_i = heapq.heappop(heaps[c])
            if available[current_i]:
                found = current_p
                available[current_i] = False
                break
        if found is not None:
            res.append(found)
        else:
            res.append(-1)

    print(' '.join(map(str, res)))

solve()

