import sys
import math

def estimate_population(samples):
    mean = sum(samples) / len(samples)
    variance = sum((x - mean) ** 2 for x in samples) / len(samples)
    if abs(variance - mean) < abs(variance - (len(samples)**2 - 1)/12):
        # Poisson distribution
        return round(mean)
    else:
        # Uniform distribution
        return round((2 * mean) - 1)

def main():
    input_lines = sys.stdin.read().splitlines()
    T = int(input_lines[0])
    index = 1
    for _ in range(T):
        samples = list(map(int, input_lines[index].split()))
        index += 1
        print(estimate_population(samples))

if __name__ == "__main__":
    main()

